class Solution {
  public long totalScore(int hp, int[] damage, int[] requirement) {
    int n = damage.length;
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + damage[i];
    long total = 0;
    for (int i = 1; i <= n; i++) {
      long need = pre[i] + requirement[i - 1] - hp;
      // count m in [0, i - 1] with pre[m] >= need
      int lo = 0, hi = i;
      while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        if (pre[mid] >= need) hi = mid;
        else lo = mid + 1;
      }
      total += i - lo;
    }
    return total;
  }
}
